function addCell(g, p, label, kind, chargeCat, opts) {
  opts = opts || {};
  var x = gx(g), y = py(p);
  var group = rectLayer.group();
  var fill = colors[kind] || colors.blank;
  var rect = group.rect(cw, ch).move(x, y).fill(fill).stroke({ color: opts.stroke || '#333', width: opts.strokeWidth || 1.2 });
  if (opts.redOutline) rect.stroke({ color: colors.red, width: 2.2 });

  var data = {
    g: g, p: p, x: x, y: y, label: label || '', kind: kind || 'blank',
    chargeCat: chargeCat || (label ? 'none' : 'blank'), rect: rect, group: group,
    config: opts.config || '', explain: opts.explain || ''
  };
  cells.push(data);
  cellGroups[(g + ',' + p)] = data;

  if (label) {
    var t = textLayer.text(function(add) {
      var parts = String(label).split('\n');
      for (var i = 0; i < parts.length; i++) {
