    .on('click', function() { selectCell(data, true); });
  if (data.text) {
    data.text.css('pointer-events', 'none');
  }
  return data;
}

function addBlank(g, p, kind, opts) {
  return addCell(g, p, '', kind || 'blank', 'blank', opts || {});
}

