for (var i = 0; i < 15; i++) {
  rectLayer.rect(cw, ch).move(fStartX + i * pitchX, lanY).fill(colors.fgreen).stroke({ color: '#333', width: 1.2 });
  rectLayer.rect(cw, ch).move(fStartX + i * pitchX, actY).fill(colors.fpink).stroke({ color: '#333', width: 1.2 });
