var currentGroup = 1;
var chargeMode = false;
var selectedCell = null;

function visibleColorForCell(c) {
  if (!chargeMode) return colors[c.kind] || colors.blank;
  return chargeColors[c.chargeCat] || chargeColors.blank;
}

function applyColorScheme() {
  cells.forEach(function(c) {
    c.rect.fill(visibleColorForCell(c));
  });
  updateLegend();
}

function updateLegend() {
  var el = document.getElementById('legendInfo');
  if (!el) return;
  if (chargeMode) {
    el.innerHTML = '<span style="color:#7b3f98">+1</span>, <span style="color:#4b8b22">+2</span>, +3, variable +, <span style="color:#b00000">−3/−2</span>, <span style="color:#304f9f">−1</span>, no common ion';
  } else {
    el.innerHTML = '<span style="color:#6b2b92">Group 1</span>, <span style="color:#4f8f20">Group 2</span>, <span style="color:#9a6d00">transition metals</span>, <span style="color:#a23a35">anion-formers</span>, halogens, noble gases';
  }
}

function groupExplanation(g) {
  if (g === 1) return 'Group 1: main-group metals usually lose 1 electron → +1 ions.';
  if (g === 2) return 'Group 2: two outer s electrons are lost → +2 ions.';
  if (g >= 3 && g <= 12) return 'Groups 3–12: transition metals often have variable charges; the column is not a single-charge rule.';
  if (g === 13) return 'Group 13: some elements form +3 ions, but the simple pattern weakens down the group.';
  if (g === 14) return 'Group 14: four valence electrons make simple monatomic ion predictions less reliable.';
  if (g === 15) return 'Group 15: nonmetals can gain 3 electrons → −3 ions.';
  if (g === 16) return 'Group 16: nonmetals often gain 2 electrons → −2 ions.';
  if (g === 17) return 'Group 17: halogens are one electron short of noble gases → −1 ions.';
  if (g === 18) return 'Group 18: noble gases already have stable valence shells; no common ion is shown.';
  return '';
}

function drawGroupHighlight() {
  highlightGroup.clear();
  cells.forEach(function(c) {
    if (c.g === currentGroup) {
      highlightGroup.rect(cw + 6, ch + 6)
        .move(c.x - 3, c.y - 3)
        .fill({ color: '#fff04a', opacity: 0.28 })
        .stroke({ color: '#d7a900', width: 2 });
    }
  });
  if (currentGroup === 3) {
    highlightGroup.rect(15 * pitchX - 5, ch + 8).move(fStartX - 4, lanY - 4).fill({ color:'#fff04a', opacity:0.16 }).stroke({ color:'#d7a900', width:1.5 });
    highlightGroup.rect(15 * pitchX - 5, ch + 8).move(fStartX - 4, actY - 4).fill({ color:'#fff04a', opacity:0.16 }).stroke({ color:'#d7a900', width:1.5 });
  }
  highlightGroup.back();
  rectLayer.front();
  textLayer.front();
  selectionLayer.front();
}

function update_groupNumber(v) {
  currentGroup = Math.max(1, Math.min(18, Math.round(v)));
  drawGroupHighlight();
  var hint = document.getElementById('groupHint');
  if (hint) hint.textContent = groupExplanation(currentGroup);
}

function toggle_colorScheme(on) {
  chargeMode = !!on;
  applyColorScheme();
  drawGroupHighlight();
}

function selectCell(c, popup) {
  selectedCell = c;
  selectionLayer.clear();
  selectionLayer.rect(cw + 8, ch + 8).move(c.x - 4, c.y - 4)
    .fill('none')
    .stroke({ color: '#111', width: 2.8 });
  selectionLayer.rect(cw + 13, ch + 13).move(c.x - 6.5, c.y - 6.5)
    .fill('none')
    .stroke({ color: '#ffcc00', width: 2.2 });

  var label = c.label ? c.label.replace(/\n/g, ' / ') : 'blank';
  var cfg = c.config || 'not shown';
  var exp = c.explain || (c.label ? 'This cell shows a common ion charge, but the reliability of the group-number shortcut depends on whether it is main-group or transition-metal chemistry.' : 'No common monatomic ion charge is listed for this position.');
  var info = document.getElementById('selectedInfo');
  if (info) info.textContent = 'Period ' + c.p + ', group ' + c.g + ' — ' + label + '. Configuration: ' + cfg + '. ' + exp;
  if (popup) {
    showPopup('Selected: ' + label, 'Period ' + c.p + ', group ' + c.g + '. Configuration: ' + cfg + '. ' + exp);
  }
}

var demoSteps = [
  {
    title:'Group 1: one electron lost',
    narration:'Group 1 metals are highlighted as +1 cation formers. Their valence configurations end in one outer s electron, so losing that electron gives a stable noble-gas-like configuration.',
    state:{groupNumber:1,colorScheme:'Element type'}
  },
  {
    title:'Group 2: two electrons lost',
    narration:'Group 2 metals form +2 ions for the same reason, but now two outer s electrons are removed. The group number directly predicts the charge for these main-group metals.',
    state:{groupNumber:2,colorScheme:'Element type'}
  },
  {
    title:'Transition-metal warning zone',
    narration:'In the d-block, the highlighted column no longer gives a simple charge rule. Cells such as Cr, Fe, Cu, Au, and Hg show multiple common charges, so their ion charges must often be learned or inferred from compounds.',
    state:{groupNumber:6,colorScheme:'Element type'}
  },
  {
    title:'Nonmetals count back from the noble gases',
    narration:'On the right side, nonmetals form anions by gaining enough electrons to reach a noble-gas configuration. Group 17 elements are one column left of the noble gases, so they typically form −1 ions.',
    state:{groupNumber:17,colorScheme:'Element type'}
  },
  {
    title:'Noble gases: no common ion',
    narration:'The noble gases already have stable valence shells, so their cells carry no ion-charge labels. Their column acts as the reference point for the negative charges of nearby nonmetals.',
    state:{groupNumber:18,colorScheme:'Element type'}
  },
  {
    title:'Compare families with charges',
    narration:'Switching to charge-value coloring reveals that periodic families and ion charges are related but not identical. The main-group pattern is clear, while the transition metals stand out as variable-charge exceptions.',
    state:{groupNumber:11,colorScheme:'Charge value'}
  }
];

var currentStep = 0;
function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  var gInput = document.getElementById('groupNumberInput');
  var gVal = document.getElementById('groupNumberVal');
  if (gInput) gInput.value = step.state.groupNumber;
  if (gVal) gVal.value = step.state.groupNumber;
  update_groupNumber(step.state.groupNumber);

