}

function groupExplanation(g) {
  if (g === 1) return 'Group 1: main-group metals usually lose 1 electron → +1 ions.';
  if (g === 2) return 'Group 2: two outer s electrons are lost → +2 ions.';
  if (g >= 3 && g <= 12) return 'Groups 3–12: transition metals often have variable charges; the column is not a single-charge rule.';
  if (g === 13) return 'Group 13: some elements form +3 ions, but the simple pattern weakens down the group.';
  if (g === 14) return 'Group 14: four valence electrons make simple monatomic ion predictions less reliable.';
  if (g === 15) return 'Group 15: nonmetals can gain 3 electrons → −3 ions.';
  if (g === 16) return 'Group 16: nonmetals often gain 2 electrons → −2 ions.';
  if (g === 17) return 'Group 17: halogens are one electron short of noble gases → −1 ions.';
  if (g === 18) return 'Group 18: noble gases already have stable valence shells; no common ion is shown.';
  return '';
